[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>CommerceForge Dev Docs</title>
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet" />
<style>
  :root {
    --bg: #0d1117;
    --bg2: #161b22;
    --bg3: #1c2128;
    --border: #30363d;
    --border2: #21262d;
    --text: #e6edf3;
    --text2: #8b949e;
    --text3: #6e7681;
    --accent: #4fc3f7;
    --accent2: #38bdf8;
    --green: #3fb950;
    --blue: #475F91;
    --blue-light: #5a7ab5;
    --radius: 8px;
    --radius2: 12px;
  }
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Space Grotesk', system-ui, sans-serif;
    font-size: 15px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }
  a { color: var(--accent); text-decoration: none; }
  a:hover { color: var(--accent2); }
  code, pre { font-family: 'JetBrains Mono', monospace; }

  /* ─── NAV ─── */
  nav {
    position: sticky; top: 0; z-index: 100;
    background: rgba(13,17,23,0.92);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border);
    padding: 0 24px;
    height: 56px;
    display: flex; align-items: center; justify-content: space-between;
  }
  .nav-logo {
    display: flex; align-items: center; gap: 10px;
    font-weight: 700; font-size: 15px; color: var(--text);
    text-decoration: none;
  }
  .nav-logo svg { width: 28px; height: 28px; }
  .nav-links { display: flex; align-items: center; gap: 4px; }
  .nav-links a {
    color: var(--text2); font-size: 14px; font-weight: 500;
    padding: 6px 12px; border-radius: 6px; transition: color .15s, background .15s;
  }
  .nav-links a:hover { color: var(--text); background: var(--bg3); }
  .nav-links a.active { color: var(--text); }
  .nav-right { display: flex; align-items: center; gap: 8px; }
  .btn-search {
    display: flex; align-items: center; gap: 8px;
    background: var(--bg3); border: 1px solid var(--border);
    color: var(--text3); font-size: 13px; font-family: inherit;
    padding: 6px 12px; border-radius: 6px; cursor: pointer; transition: border-color .15s;
    white-space: nowrap;
  }
  .btn-search:hover { border-color: var(--accent); color: var(--text2); }
  .btn-login {
    background: var(--blue); color: #fff;
    font-size: 13px; font-weight: 600; font-family: inherit;
    padding: 6px 14px; border-radius: 6px; border: none; cursor: pointer;
    transition: background .15s;
  }
  .btn-login:hover { background: var(--blue-light); }
  .nav-mobile-toggle { display: none; background: none; border: none; color: var(--text); cursor: pointer; padding: 6px; }

  /* ─── HERO ─── */
  .hero {
    padding: 80px 24px 64px;
    max-width: 900px; margin: 0 auto; text-align: center;
    position: relative;
  }
  .hero::before {
    content: '';
    position: absolute; inset: 0;
    background: radial-gradient(ellipse 60% 50% at 50% 0%, rgba(71,95,145,0.18) 0%, transparent 70%);
    pointer-events: none;
  }
  .hero-badge {
    display: inline-flex; align-items: center; gap: 6px;
    background: rgba(71,95,145,0.15); border: 1px solid rgba(71,95,145,0.35);
    color: var(--accent); font-size: 12px; font-weight: 600;
    padding: 4px 12px; border-radius: 100px; margin-bottom: 24px;
    letter-spacing: 0.05em; text-transform: uppercase;
  }
  .hero h1 {
    font-size: clamp(32px, 5vw, 52px);
    font-weight: 700; line-height: 1.1;
    color: var(--text); letter-spacing: -0.02em; margin-bottom: 20px;
  }
  .hero h1 span { color: var(--accent); }
  .hero-sub {
    font-size: clamp(15px, 2vw, 17px);
    color: var(--text2); max-width: 680px; margin: 0 auto 36px;
    line-height: 1.7;
  }
  .hero-ctas { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
  .btn-primary {
    background: var(--blue); color: #fff;
    padding: 10px 20px; border-radius: 7px;
    font-size: 14px; font-weight: 600; font-family: inherit;
    border: none; cursor: pointer; transition: background .15s, transform .1s;
    display: inline-flex; align-items: center; gap: 6px;
  }
  .btn-primary:hover { background: var(--blue-light); transform: translateY(-1px); }
  .btn-outline {
    background: transparent; color: var(--text2);
    padding: 10px 20px; border-radius: 7px;
    font-size: 14px; font-weight: 500; font-family: inherit;
    border: 1px solid var(--border); cursor: pointer; transition: border-color .15s, color .15s, transform .1s;
    display: inline-flex; align-items: center; gap: 6px;
    text-decoration: none;
  }
  .btn-outline:hover { border-color: var(--accent); color: var(--text); transform: translateY(-1px); }

  /* ─── SECTION COMMON ─── */
  .section { padding: 64px 24px; max-width: 1100px; margin: 0 auto; }
  .section-label {
    font-size: 11px; font-weight: 700; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--accent); margin-bottom: 12px;
  }
  .section-title {
    font-size: clamp(22px, 3vw, 30px); font-weight: 700;
    color: var(--text); letter-spacing: -0.02em; margin-bottom: 8px;
  }
  .section-sub {
    font-size: 15px; color: var(--text2); max-width: 600px; line-height: 1.7;
  }
  .section-divider { border: none; border-top: 1px solid var(--border2); }

  /* ─── PRODUCT CARDS ─── */
  .products-grid {
    display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;
    margin-top: 40px;
  }
  .product-card {
    background: var(--bg2); border: 1px solid var(--border);
    border-radius: var(--radius2); padding: 28px 24px;
    display: flex; flex-direction: column; gap: 12px;
    transition: border-color .2s, transform .2s;
    position: relative; overflow: hidden;
  }
  .product-card::before {
    content: ''; position: absolute; inset: 0;
    background: radial-gradient(circle at top left, var(--card-glow, rgba(71,95,145,0.08)) 0%, transparent 60%);
    pointer-events: none;
  }
  .product-card:hover { border-color: var(--accent); transform: translateY(-2px); }
  .product-card-icon {
    width: 40px; height: 40px; border-radius: 8px;
    background: rgba(71,95,145,0.2); border: 1px solid rgba(71,95,145,0.3);
    display: flex; align-items: center; justify-content: center;
    font-size: 18px;
  }
  .product-card h3 { font-size: 18px; font-weight: 700; color: var(--text); }
  .product-card p { font-size: 14px; color: var(--text2); line-height: 1.6; flex: 1; }
  .product-card-cta {
    margin-top: 4px;
    display: inline-flex; align-items: center; gap: 6px;
    color: var(--accent); font-size: 14px; font-weight: 600;
    text-decoration: none; transition: gap .15s;
  }
  .product-card-cta:hover { gap: 10px; color: var(--accent); }
  .card-apps { --card-glow: rgba(63,185,80,0.08); }
  .card-storefronts { --card-glow: rgba(79,195,247,0.08); }
  .card-agents { --card-glow: rgba(210,153,247,0.08); }

  /* ─── CLI SETUP ─── */
  .cli-section {
    background: var(--bg2); border: 1px solid var(--border);
    border-radius: var(--radius2); padding: 40px; margin-top: 64px;
    position: relative; overflow: hidden;
  }
  .cli-section::before {
    content: ''; position: absolute; top: 0; right: 0;
    width: 300px; height: 300px;
    background: radial-gradient(circle, rgba(71,95,145,0.12) 0%, transparent 70%);
    pointer-events: none;
  }
  .cli-header { margin-bottom: 32px; }
  .cli-accordions { display: flex; flex-direction: column; gap: 8px; }
  .accordion-item {
    background: var(--bg3); border: 1px solid var(--border2);
    border-radius: var(--radius); overflow: hidden;
    transition: border-color .2s;
  }
  .accordion-item.open { border-color: var(--accent); }
  .accordion-trigger {
    width: 100%; background: none; border: none; cursor: pointer;
    padding: 16px 20px; display: flex; align-items: center; justify-content: space-between;
    color: var(--text); font-size: 15px; font-weight: 600; font-family: inherit;
    text-align: left; transition: background .15s;
  }
  .accordion-trigger:hover { background: rgba(255,255,255,0.03); }
  .accordion-trigger-left { display: flex; align-items: center; gap: 12px; }
  .accordion-number {
    width: 24px; height: 24px; border-radius: 50%;
    background: rgba(71,95,145,0.25); border: 1px solid rgba(71,95,145,0.4);
    display: flex; align-items: center; justify-content: center;
    font-size: 12px; font-weight: 700; color: var(--accent);
    flex-shrink: 0;
  }
  .accordion-chevron {
    color: var(--text3); transition: transform .2s; flex-shrink: 0;
  }
  .accordion-item.open .accordion-chevron { transform: rotate(180deg); }
  .accordion-body { display: none; padding: 0 20px 20px; }
  .accordion-item.open .accordion-body { display: block; }
  .accordion-steps { counter-reset: steps; display: flex; flex-direction: column; gap: 20px; }
  .accordion-step { display: flex; gap: 16px; }
  .step-num {
    width: 22px; height: 22px; border-radius: 50%;
    background: var(--bg); border: 1px solid var(--border);
    display: flex; align-items: center; justify-content: center;
    font-size: 11px; font-weight: 700; color: var(--text3);
    flex-shrink: 0; margin-top: 2px;
  }
  .step-content { flex: 1; }
  .step-content p { font-size: 14px; color: var(--text2); margin-bottom: 10px; }
  .code-block {
    background: var(--bg); border: 1px solid var(--border2);
    border-radius: var(--radius); overflow: hidden;
  }
  .code-tabs {
    display: flex; border-bottom: 1px solid var(--border2);
    padding: 0 4px;
  }
  .code-tab {
    background: none; border: none; cursor: pointer;
    padding: 8px 14px; font-size: 12px; font-weight: 600; font-family: inherit;
    color: var(--text3); border-bottom: 2px solid transparent;
    transition: color .15s, border-color .15s; margin-bottom: -1px;
  }
  .code-tab.active { color: var(--accent); border-bottom-color: var(--accent); }
  .code-tab:hover:not(.active) { color: var(--text2); }
  .code-content { display: none; }
  .code-content.active { display: block; }
  .code-pre {
    padding: 14px 16px; margin: 0;
    font-size: 13px; color: var(--green);
    overflow-x: auto; white-space: pre;
  }
  .code-line-comment { color: var(--text3); }
  .code-line-cmd { color: var(--green); }
  .code-copy {
    display: flex; align-items: center; justify-content: space-between;
    padding: 6px 16px 10px; border-top: 1px solid var(--border2);
  }
  .copy-btn {
    background: none; border: 1px solid var(--border2); color: var(--text3);
    font-size: 11px; font-family: inherit; padding: 3px 10px; border-radius: 4px;
    cursor: pointer; transition: border-color .15s, color .15s;
  }
  .copy-btn:hover { border-color: var(--accent); color: var(--accent); }

  /* ─── LAUNCH CTA ─── */
  .launch-grid {
    display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 40px;
  }
  .launch-card {
    background: var(--bg2); border: 1px solid var(--border);
    border-radius: var(--radius2); padding: 28px;
    display: flex; flex-direction: column; gap: 10px;
    transition: border-color .2s;
  }
  .launch-card:hover { border-color: var(--accent); }
  .launch-card h3 { font-size: 17px; font-weight: 700; color: var(--text); }
  .launch-card p { font-size: 14px; color: var(--text2); line-height: 1.6; flex: 1; }
  .launch-card-cta {
    display: inline-flex; align-items: center; gap: 6px;
    color: var(--accent); font-size: 14px; font-weight: 600;
    text-decoration: none; margin-top: 4px; transition: gap .15s;
  }
  .launch-card-cta:hover { gap: 10px; }

  /* ─── COMMUNITY ─── */
  .community-grid {
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-top: 32px;
  }
  .community-card {
    background: var(--bg2); border: 1px solid var(--border);
    border-radius: var(--radius); padding: 20px;
    display: flex; flex-direction: column; gap: 8px;
    transition: border-color .2s, transform .15s; text-decoration: none;
  }
  .community-card:hover { border-color: var(--accent); transform: translateY(-2px); }
  .community-card-icon { font-size: 20px; }
  .community-card h4 { font-size: 14px; font-weight: 700; color: var(--text); }
  .community-card p { font-size: 13px; color: var(--text2); line-height: 1.5; }
  .community-card-arrow { color: var(--accent); font-size: 12px; margin-top: auto; }

  /* ─── FOOTER ─── */
  footer {
    background: var(--bg2); border-top: 1px solid var(--border);
    padding: 48px 24px 32px; margin-top: 80px;
  }
  .footer-inner { max-width: 1100px; margin: 0 auto; }
  .footer-grid {
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-bottom: 40px;
  }
  .footer-col h5 {
    font-size: 12px; font-weight: 700; letter-spacing: 0.08em;
    text-transform: uppercase; color: var(--text3); margin-bottom: 14px;
  }
  .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
  .footer-col ul li a {
    font-size: 14px; color: var(--text2); text-decoration: none; transition: color .15s;
  }
  .footer-col ul li a:hover { color: var(--accent); }
  .footer-bottom {
    border-top: 1px solid var(--border2); padding-top: 24px;
    display: flex; justify-content: space-between; align-items: center;
    flex-wrap: wrap; gap: 12px;
  }
  .footer-brand { font-size: 14px; font-weight: 700; color: var(--text); }
  .footer-copy { font-size: 12px; color: var(--text3); }

  /* ─── RESPONSIVE ─── */
  @media (max-width: 1024px) {
    .community-grid { grid-template-columns: repeat(2, 1fr); }
    .footer-grid { grid-template-columns: repeat(2, 1fr); }
  }
  @media (max-width: 768px) {
    .products-grid { grid-template-columns: 1fr; }
    .launch-grid { grid-template-columns: 1fr; }
    .community-grid { grid-template-columns: 1fr 1fr; }
    .hero { padding: 48px 20px 40px; }
    .hero h1 { font-size: 28px; }
    .hero-ctas { flex-direction: column; align-items: center; }
    .btn-primary, .btn-outline { width: 100%; max-width: 300px; justify-content: center; }
    .cli-section { padding: 24px 16px; }
    .nav-links { display: none; }
    .nav-mobile-toggle { display: flex; }
    .section { padding: 48px 20px; }
    .footer-grid { grid-template-columns: 1fr 1fr; }
  }
  @media (max-width: 480px) {
    .community-grid { grid-template-columns: 1fr; }
    .footer-grid { grid-template-columns: 1fr; }
    .footer-bottom { flex-direction: column; text-align: center; }
  }
</style>
</head>
<body>

<!-- NAV -->
<nav>
  <a href="index.html" class="nav-logo">
    <svg viewBox="0 0 28 28" fill="none" xmlns="http://www.w3.org/2000/svg">
      <rect width="28" height="28" rx="6" fill="#475F91"/>
      <path d="M7 8h14M7 14h10M7 20h12" stroke="white" stroke-width="2.2" stroke-linecap="round"/>
    </svg>
    CommerceForge
  </a>
  <div class="nav-links">
    <a href="apps-build.html">Apps</a>
    <a href="storefronts.html">Storefronts</a>
    <a href="agents.html">Agents</a>
    <a href="#" style="color:var(--text2)">References</a>
    <a href="support.html">Help</a>
  </div>
  <div class="nav-right">
    <button class="btn-search">
      <svg width="14" height="14" viewBox="0 0 16 16" fill="currentColor"><path d="M11.742 10.344a6.5 6.5 0 1 0-1.397 1.398h-.001c.03.04.062.078.098.115l3.85 3.85a1 1 0 0 0 1.415-1.414l-3.85-3.85a1.007 1.007 0 0 0-.115-.099zm-5.242 1.156a5.5 5.5 0 1 1 0-11 5.5 5.5 0 0 1 0 11z"/></svg>
      Ask assistant
    </button>
    <button class="btn-login">Log in</button>
  </div>
  <button class="nav-mobile-toggle" aria-label="Menu">
    <svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M3 5h14a1 1 0 0 1 0 2H3a1 1 0 0 1 0-2zm0 4h14a1 1 0 0 1 0 2H3a1 1 0 0 1 0-2zm0 4h14a1 1 0 0 1 0 2H3a1 1 0 0 1 0-2z"/></svg>
  </button>
</nav>

<!-- HERO -->
<div class="hero">
  <div class="hero-badge">
    <svg width="8" height="8" viewBox="0 0 8 8"><circle cx="4" cy="4" r="4" fill="currentColor"/></svg>
    Developer Platform
  </div>
  <h1>CommerceForge<br><span>Dev Docs</span></h1>
  <p class="hero-sub">Learn how to build an app, or customize your storefront. Whether you're just getting started, deep in the development process, or ready to distribute and monetize your work, CommerceForge's docs, dev tools and frameworks make building easy and efficient.</p>
  <div class="hero-ctas">
    <a href="apps-build.html" class="btn-primary">Build your first app →</a>
    <a href="storefronts.html" class="btn-outline">Build a storefront →</a>
    <a href="agents.html" class="btn-outline">Build agents with UCP →</a>
  </div>
</div>

<hr class="section-divider" />

<!-- PRODUCT CARDS -->
<div class="section">
  <div class="section-label">Platform Areas</div>
  <div class="section-title">Build across the commerce platform</div>
  <p class="section-sub">Three powerful pillars for creating rich commerce experiences at every layer.</p>

  <div class="products-grid">
    <!-- Apps -->
    <div class="product-card card-apps">
      <div class="product-card-icon">⚡</div>
      <h3>Apps</h3>
      <p>Extend CommerceForge's core functionality with apps that integrate into the admin, online store, checkout and more. Build once, deploy everywhere.</p>
      <a href="apps-build.html" class="product-card-cta">Build your first app →</a>
    </div>
    <!-- Storefronts -->
    <div class="product-card card-storefronts">
      <div class="product-card-icon">🏪</div>
      <h3>Storefronts</h3>
      <p>Help merchants express their unique brand by building a custom theme or Hydrogen storefront. Flexible, composable, and built for performance.</p>
      <a href="storefronts.html" class="product-card-cta">Build a storefront →</a>
    </div>
    <!-- Agents -->
    <div class="product-card card-agents">
      <div class="product-card-icon">🤖</div>
      <h3>Agents</h3>
      <p>Build agentic shopping experiences powered by CommerceForge merchants, from product discovery to checkout via Universal Commerce Protocol.</p>
      <a href="agents.html" class="product-card-cta">Build agents with UCP →</a>
    </div>
  </div>
</div>

<hr class="section-divider" />

<!-- CLI SETUP -->
<div class="section">
  <div class="cli-section">
    <div class="cli-header">
      <div class="section-label">CLI 3.0</div>
      <div class="section-title">Accelerate development with CommerceForge CLI 3.0</div>
      <p class="section-sub" style="margin-top:8px;">Initialize new apps, themes, and headless storefronts in an instant with the latest CommerceForge CLI. A single command installs all the dependencies you need, including the CLI itself, so you can dive straight into development.</p>
    </div>

    <div class="cli-accordions" id="cliAccordions">

      <!-- Apps Accordion -->
      <div class="accordion-item" id="acc-apps">
        <button class="accordion-trigger" onclick="toggleAccordion('acc-apps')">
          <span class="accordion-trigger-left">
            <span class="accordion-number">1</span>
            Apps
          </span>
          <svg class="accordion-chevron" width="16" height="16" viewBox="0 0 16 16" fill="currentColor"><path d="M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708z"/></svg>
        </button>
        <div class="accordion-body">
          <div class="accordion-steps">
            <div class="accordion-step">
              <span class="step-num">1</span>
              <div class="step-content">
                <p>Install CommerceForge CLI globally.</p>
                <div class="code-block">
                  <div class="code-tabs">
                    <button class="code-tab active" onclick="switchTab(this, 'apps-install')">npm</button>
                    <button class="code-tab" onclick="switchTab(this, 'apps-install')">yarn</button>
                    <button class="code-tab" onclick="switchTab(this, 'apps-install')">pnpm</button>
                  </div>
                  <div class="code-content active" data-pkg="npm">
                    <pre class="code-pre"><span class="code-line-cmd">npm i -g @commerceforge/cli@latest</span></pre>
                  </div>
                  <div class="code-content" data-pkg="yarn">
                    <pre class="code-pre"><span class="code-line-cmd">yarn global add @commerceforge/cli@latest</span></pre>
                  </div>
                  <div class="code-content" data-pkg="pnpm">
                    <pre class="code-pre"><span class="code-line-cmd">pnpm add -g @commerceforge/cli@latest</span></pre>
                  </div>
                  <div class="code-copy">
                    <span style="font-size:12px;color:var(--text3)">Terminal</span>
                    <button class="copy-btn" onclick="copyCode(this)">Copy</button>
                  </div>
                </div>
              </div>
            </div>
            <div class="accordion-step">
              <span class="step-num">2</span>
              <div class="step-content">
                <p>Navigate to the directory where you want to create your app.</p>
              </div>
            </div>
            <div class="accordion-step">
              <span class="step-num">3</span>
              <div class="step-content">
                <p>Run the command to create a new app. Your app will be added as a new subdirectory.</p>
                <div class="code-block">
