<script>
  function toggleAccordion(id) {
    const all = document.querySelectorAll('.accordion-item');
    all.forEach(item => {
      if (item.id === id) {
        item.classList.toggle('open');
      } else {
        item.classList.remove('open');
      }
    });
  }

  function switchTab(btn, group) {
    const block = btn.closest('.code-block');
    const tabs = block.querySelectorAll('.code-tab');
    const contents = block.querySelectorAll('.code-content');
    const idx = Array.from(tabs).indexOf(btn);
    tabs.forEach(t => t.classList.remove('active'));
    contents.forEach(c => c.classList.remove('active'));
    btn.classList.add('active');
    if (contents[idx]) contents[idx].classList.add('active');
  }

  function copyCode(btn) {
    const block = btn.closest('.code-block');
    const active = block.querySelector('.code-content.active pre') || block.querySelector('pre');
    if (active) {
      navigator.clipboard.writeText(active.textContent.trim()).then(() => {
        const orig = btn.textContent;
        btn.textContent = 'Copied!';
        setTimeout(() => btn.textContent = orig, 1500);
      });
    }
  }

  // Open first accordion by default
  document.getElementById('acc-apps').classList.add('open');
